// Payment Page
const PaymentPage: React.FC<{
  amount: number;
  onSuccess: () => void;
  onFail: () => void;
  onBack: () => void;
}> = ({ amount, onSuccess, onFail, onBack }) => {
  const [paymentMethod, setPaymentMethod] = useState<'upi' | 'cash' | ''>('');
  const [processing, setProcessing] = useState(false);

  const handlePayment = (method: 'upi' | 'cash') => {
    if (method === 'upi') {
      // Create UPI payment link
      const upiId = '8709276546@ptsbi';
      const payeeName = 'QR Booking System';
      const transactionNote = 'Booking Payment';

      // UPI deep link format
      const upiLink = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(payeeName)}&am=${amount}&cu=INR&tn=${encodeURIComponent(transactionNote)}`;

      // Try to open UPI app, fallback to showing UPI ID
      window.location.href = upiLink;

      // Show processing state
      setProcessing(true);

      // Auto-success after 5 seconds (assuming user completes payment)
      setTimeout(() => {
        setProcessing(false);
        const userConfirm = window.confirm('Have you completed the payment? Click OK if payment is successful, Cancel to try again.');
        if (userConfirm) {
          onSuccess();
        } else {
          // User can try again
        }
      }, 5000);
    } else {
      // Cash payment simulation
      setProcessing(true);
      setTimeout(() => {
        setProcessing(false);
        onSuccess();
      }, 2000);
    }
  };

  if (processing) {
    return (
      <div style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '20px'
      }}>
        <div style={{
